um":["spec_evidence_source"],"chainring_teeth_min":["spec_evidence_source"],"chainring_teeth_max":["spec_evidence_source"]},"helpers":{"chain_guide_mount_options":"Un SKU puede documentar más de un estándar. Tener los anclajes no certifica un cuadro: las exclusiones van aparte.","chain_guide_included_parts":"Componentes realmente incluidos y cuál viene montado. Un rango total de platos no vuelve intercambiables sus placas. El peso aquí corresponde a la pieza suelta; un peso del conjunto montado pertenece a su configuración completa.","chain_guide_frame_exclusions":"Incompatibilidades que publica la fuente, por modelo y generación o por clase de cuadro.","chain_guide_chainline_adjustment_mm":"Recorrido que permite el ajuste, no una línea de cadena. Una ficha que rotula «Chainline: 7,5 mm de ajuste» declara recorrido.","chain_guide_chainline_datum":"Desde qué referencia mide la fuente la línea de cadena instalada. Sin datum, la cifra no se compara con otra ficha.","chainline_mm":"Línea de cadena instalada según la fuente y su datum. No recibe el recorrido de ajuste, que tiene su propio campo.","chainring_teeth_min":"Capacidad publicada para esta variante y las configuraciones que documenta su fabricante. No se calcula uniendo rangos de piezas.","chainring_teeth_max":"Capacidad publicada para esta variante y las configuraciones que documenta su fabricante. No se calcula uniendo rangos de piezas.","chain_guide_assembled_weights":"Peso publicado del conjunto completo con una pieza concreta montada. No es el peso de esa pieza ni del envase con sus repuestos."},"evidence_requirements":{"chain_guide_mount_type":"oem_spec","chainring_teeth_min":"oem_spec","chainring_teeth_max":"oem_spec","chainring_teeth":"name_reading_hint_only","chainline_mm":"oem_spec","spec_evidence_source":"oem_or_package","chain_guide_mount_options":"oem_or_package","chain_guide_included_parts":"oem_or_package","chain_guide_frame_exclusions":"oem_or_package","chain_guide_chainline_adjustment_mm":"oem_or_package","chain_guide_chainline_datum":"oem_or_package","chain_guide_assembled_weights":"oem_or_package"},"scalar_ordered_pairs":[["chainring_teeth_min","chainring_teeth_max"]],"row_conditions":{"version":1,"fields":{"chain_guide_frame_exclusions":{"allowed_when":{"brand":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"model":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"declared_interface":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Interfaz o estándar documentado"}]]}},"required_when":{"brand":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"model":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Modelo documentado"}]]},"declared_interface":{"kind":"when","rows":[[{"field":"scope_kind","operator":"eq","value_type":"token","value":"Interfaz o estándar documentado"}]]}}}}},"row_coherence":{"version":1,"links":[{"id":"assembled_weight_names_its_mounted_piece","field":"chain_guide_assembled_weights","column":"mounted_part_reference","target_field":"chain_guide_included_parts","label_columns":["part_identity"]}]}},"id":"0aaec6de-c69d-4e1e-9b03-995805a30a9c","is_active":true,"key":"chain_guide","name":"Guía de Cadena","technical_family":"chain_guide","tenant_id":null}}],"adjudication":{"status":"candidate_under_sole_owner_review","scope":"Hanger, pulley and chain guide owners; extenders, full-mount derailleurs, identity and fill stay outside.","preimage":"Fresh 2026-09-16 production capture equals the 2026-09-08 final preimage in templates, fields and shared definitions; effective bindings 23+7+3 -> 28+7+3.","hanger":"Frame and derailleur interfaces are declarations of this hanger; a title never resolves them.","pulley":"Position, speeds, profile and dimensions are per declared unit; rotation and torque need the exact manual.","chain_guide":"Line-wide interchange is a cross-product claim, not a fact of one SKU.","legacy":"Published frame hint, hanger interface, mount type and teeth readings are retained without becoming active compatibility.","reviews":"Root decisions and the row-order delta review (2026-09-08) left no open blocker; adoption then 33/0, now repeated on 38.","released_client":"f51f3777 decodes row_conditions, row_coherence and two-element scalar pairs; one two-element pair here, no strict order.","compatibility_and_fill_not_approved":true,"new_scalar_surfaces":["chain_guide_chainline_adjustment_mm","chainring_teeth_max","chainring_teeth_min","hanger_derailleur_interface","hanger_frame_interface","pulley_bearing_construction","pulley_bearing_element_material","pulley_bore_diameter_mm","pulley_declared_position","pulley_declared_speeds","pulley_outer_diameter_mm","pulley_package_kind","pulley_tooth_profile","pulley_unit_count","pulley_width_mm"]},"product_writes":false,"fill_allowed":false,"mechanical_approval":false}$nd_catalog$::jsonb);
create temporary table nd_publication_before on commit drop as select
 (select md5(coalesce(jsonb_agg(to_jsonb(f) order by f.id),'[]')::text) from public.spec_facts f) facts,
 (select md5(coalesce(jsonb_agg(jsonb_build_array(p.id,p.spec_revision,p.spec_template_id,p.spec_reference_id) order by p.id),'[]')::text) from public.products p) products,
 (select md5(coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]')::text) from public.product_spec_references r) references,
 (select md5(coalesce(jsonb_agg(to_jsonb(m) order by m.id),'[]')::text) from public.category_tech_mappings m) category_defaults;

do $publish$
declare doc jsonb; v_wanted jsonb; v_actual jsonb; patch jsonb;
begin
 select d.doc into doc from nd_publication_document d;
 if md5(pg_get_functiondef(to_regprocedure(
   'public.spec_validate_draft_internal_v1(uuid,jsonb,text,text,text,text)')))
   is distinct from 'ac0738d5c2039412b603dc71adc41721' then
   raise exception 'Unreviewed specification validator';
 end if;
 if exists(select 1 from jsonb_array_elements(doc->'records'->'spec_templates') w
    join public.spec_templates t on t.key=w->>'key'
    and (t.tenant_id is null or t.tenant_id=(doc->>'audited_tenant_id')::uuid)
    where t.id<>(w->>'id')::uuid)
 or exists(select 1 from jsonb_array_elements(doc->'records'->'spec_definitions') w
    join public.spec_definitions d on d.key=w->>'key'
    and (d.tenant_id is null or d.tenant_id=(doc->>'audited_tenant_id')::uuid)
    where d.id<>(w->>'id')::uuid) then
   raise exception 'Publication key collision';
 end if;
 if exists(select 1 from jsonb_array_elements(doc->'reused_definitions') wanted
   left join public.spec_definitions actual on actual.id=(wanted->>'id')::uuid
   where actual.id is null or to_jsonb(actual) is distinct from wanted-'options'
   or (select coalesce(jsonb_agg(to_jsonb(v) order by v.id),'[]')
       from public.spec_definition_values v where v.spec_definition_id=actual.id)
      is distinct from wanted->'options') then
   raise exception 'Forward publication shared-definition drift';
 end if;
 if ((not exists (
 select 1 from jsonb_array_elements(doc->'records'->'spec_definitions') wanted
 left join public.spec_definitions actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or (select jsonb_object_agg(k,to_jsonb(actual)->k)
 from jsonb_object_keys(wanted) k) is distinct from wanted)) and
(not exists (
 select 1 from jsonb_array_elements(doc->'records'->'spec_definition_values') wanted
 left join public.spec_definition_values actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or (select jsonb_object_agg(k,to_jsonb(actual)->k)
 from jsonb_object_keys(wanted) k) is distinct from wanted)) and
(not exists (
 select 1 from jsonb_array_elements(doc->'records'->'spec_templates') wanted
 left join public.spec_templates actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or (select jsonb_object_agg(k,to_jsonb(actual)->k)
 from jsonb_object_keys(wanted) k) is distinct from wanted)) and
(not exists (
 select 1 from jsonb_array_elements(doc->'records'->'spec_template_fields') wanted
 left join public.spec_template_fields actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or (select jsonb_object_agg(k,to_jsonb(actual)->k)
 from jsonb_object_keys(wanted) k) is distinct from wanted)) and
(not exists (select 1 from public.spec_template_fields f
 where f.template_id in (select (t->>'id')::uuid from jsonb_array_elements(doc->'records'->'spec_templates') t)
 and f.id not in (select (f->>'id')::uuid from jsonb_array_elements(doc->'records'->'spec_template_fields') f))) and
(not exists (select 1 from public.spec_definition_values v
 where v.spec_definition_id in (select (d->>'id')::uuid from jsonb_array_elements(doc->'records'->'spec_definitions') d)
 and v.id not in (select (v->>'id')::uuid from jsonb_array_elements(doc->'records'->'spec_definition_values') v))) and
(not exists (select 1 from jsonb_array_elements(doc->'reused_definitions') wanted
 left join public.spec_definitions d on d.id=(wanted->>'id')::uuid
 where d.id is null or to_jsonb(d) is distinct from wanted-'options'
 or (select coalesce(jsonb_agg(to_jsonb(v) order by v.id),'[]')
     from public.spec_definition_values v where v.spec_definition_id=d.id) is distinct from wanted->'options'))) then
   return; -- Exact replay must not increment any revision.
 end if;
 if not ((not exists (
 select 1 from jsonb_array_elements(doc->'before'->'spec_templates') wanted
 left join public.spec_templates actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or to_jsonb(actual) is distinct from wanted)) and
(not exists (
 select 1 from jsonb_array_elements(doc->'before'->'spec_template_fields') wanted
 left join public.spec_template_fields actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or to_jsonb(actual) is distinct from wanted)) and
(not exists (select 1 from public.spec_template_fields actual
 where actual.template_id in (select (t->>'id')::uuid
 from jsonb_array_elements(doc->'before'->'spec_templates') t)
 and actual.id not in (select (f->>'id')::uuid
 from jsonb_array_elements(doc->'before'->'spec_template_fields') f))) and
(not exists (select 1
 from jsonb_array_elements(doc->'records'->'spec_template_fields') wanted
 join public.spec_template_fields actual on actual.id=(wanted->>'id')::uuid
 where wanted->>'id' not in (select f->>'id'
 from jsonb_array_elements(doc->'before'->'spec_template_fields') f)))) then
   raise exception 'Forward publication preimage drift';
 end if;
 
 for v_wanted in select value from jsonb_array_elements(doc->'records'->'spec_definitions') loop
   select to_jsonb(t) into v_actual from public.spec_definitions t where id=(v_wanted->>'id')::uuid;
   if found then
     raise exception 'Forward publication new-record collision in spec_definitions: %',v_wanted->>'id';
   end if;
   insert into public.spec_definitions(id,tenant_id,key,label,data_type,unit,allowed_values,validation_rules,is_customer_visible,is_compatibility_relevant,description,is_filterable,is_required_by_default,is_mechanic_visible,group_name,sort_order)
   select id,tenant_id,key,label,data_type,unit,allowed_values,validation_rules,is_customer_visible,is_compatibility_relevant,description,is_filterable,is_required_by_default,is_mechanic_visible,group_name,sort_order from jsonb_populate_record(null::public.spec_definitions,v_wanted);
 end loop;
 for v_wanted in select value from jsonb_array_elements(doc->'records'->'spec_definition_values') loop
   select to_jsonb(t) into v_actual from public.spec_definition_values t where id=(v_wanted->>'id')::uuid;
   if found then
     raise exception 'Forward publication new-record collision in spec_definition_values: %',v_wanted->>'id';
   end if;
   insert into public.spec_definition_values(id,tenant_id,spec_definition_id,code,label,sort_order,is_active)
   select id,tenant_id,spec_definition_id,code,label,sort_order,is_active from jsonb_populate_record(null::public.spec_definition_values,v_wanted);
 end loop;
 -- Template first, then changed/new fields. Each real edit bumps the native
 -- revision once; unchanged fields never receive an UPDATE.
 for patch in select value from jsonb_array_elements(doc->'patches')
     where value->>'table'='spec_templates' loop
   update public.spec_templates set form_contract=patch->'after'->'form_contract'
   where id=(patch->'before'->>'id')::uuid;
 end loop;
 for patch in select value from jsonb_array_elements(doc->'patches')
     where value->>'table'='spec_template_fields' loop
   update public.spec_template_fields set (section_key,sort_order,is_required,visibility_rules,option_rules,constraint_rules,default_value_json,helper_text)=(
     select section_key,sort_order,is_required,visibility_rules,option_rules,constraint_rules,default_value_json,helper_text from jsonb_populate_record(
       null::public.spec_template_fields,patch->'after'))
   where id=(patch->'before'->>'id')::uuid;
 end loop;
 for v_wanted in select value from jsonb_array_elements(doc->'records'->'spec_template_fields')
     where value->>'id' not in (select f->>'id'
       from jsonb_array_elements(doc->'before'->'spec_template_fields') f) loop
   insert into public.spec_template_fields(id,tenant_id,template_id,spec_definition_id,section_key,sort_order,is_required,visibility_rules,option_rules,constraint_rules,default_value_json,helper_text)
   select id,tenant_id,template_id,spec_definition_id,section_key,sort_order,is_required,visibility_rules,option_rules,constraint_rules,default_value_json,helper_text from jsonb_populate_record(null::public.spec_template_fields,v_wanted);
 end loop;
end $publish$;

set constraints all immediate;
select 1/(case when (not exists (
 select 1 from jsonb_array_elements(doc->'records'->'spec_definitions') wanted
 left join public.spec_definitions actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or (select jsonb_object_agg(k,to_jsonb(actual)->k)
 from jsonb_object_keys(wanted) k) is distinct from wanted)) and
(not exists (
 select 1 from jsonb_array_elements(doc->'records'->'spec_definition_values') wanted
 left join public.spec_definition_values actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or (select jsonb_object_agg(k,to_jsonb(actual)->k)
 from jsonb_object_keys(wanted) k) is distinct from wanted)) and
(not exists (
 select 1 from jsonb_array_elements(doc->'records'->'spec_templates') wanted
 left join public.spec_templates actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or (select jsonb_object_agg(k,to_jsonb(actual)->k)
 from jsonb_object_keys(wanted) k) is distinct from wanted)) and
(not exists (
 select 1 from jsonb_array_elements(doc->'records'->'spec_template_fields') wanted
 left join public.spec_template_fields actual on actual.id=(wanted->>'id')::uuid
 where actual.id is null or (select jsonb_object_agg(k,to_jsonb(actual)->k)
 from jsonb_object_keys(wanted) k) is distinct from wanted)) and
(not exists (select 1 from public.spec_template_fields f
 where f.template_id in (select (t->>'id')::uuid from jsonb_array_elements(doc->'records'->'spec_templates') t)
 and f.id not in (select (f->>'id')::uuid from jsonb_array_elements(doc->'records'->'spec_template_fields') f))) and
(not exists (select 1 from public.spec_definition_values v
 where v.spec_definition_id in (select (d->>'id')::uuid from jsonb_array_elements(doc->'records'->'spec_definitions') d)
 and v.id not in (select (v->>'id')::uuid from jsonb_array_elements(doc->'records'->'spec_definition_values') v))) and
(not exists (select 1 from jsonb_array_elements(doc->'reused_definitions') wanted
 left join public.spec_definitions d on d.id=(wanted->>'id')::uuid
 where d.id is null or to_jsonb(d) is distinct from wanted-'options'
 or (select coalesce(jsonb_agg(to_jsonb(v) order by v.id),'[]')
     from public.spec_definition_values v where v.spec_definition_id=d.id) is distinct from wanted->'options')) then 1 else 0 end) as exact_metadata
from nd_publication_document;
select 1/(case when b.facts=(select md5(coalesce(jsonb_agg(to_jsonb(f) order by f.id),'[]')::text) from public.spec_facts f)
 and b.products=(select md5(coalesce(jsonb_agg(jsonb_build_array(p.id,p.spec_revision,p.spec_template_id,p.spec_reference_id) order by p.id),'[]')::text) from public.products p)
 and b.references=(select md5(coalesce(jsonb_agg(to_jsonb(r) order by r.id),'[]')::text) from public.product_spec_references r)
 and b.category_defaults=(select md5(coalesce(jsonb_agg(to_jsonb(m) order by m.id),'[]')::text) from public.category_tech_mappings m)
 then 1 else 0 end) as product_observations_and_identity_unchanged from nd_publication_before b;
commit;
